def main()->int:
    ap=argparse.ArgumentParser(); ap.add_argument('--zip',required=True,type=Path); ap.add_argument('--sidecar',required=True,type=Path); ap.add_argument('--source-v66',required=True,type=Path); ap.add_argument('--build-report',required=True,type=Path); ap.add_argument('--family-report',required=True,type=Path); ap.add_argument('--shared-report',required=True,type=Path); ap.add_argument('--observer-report',required=True,type=Path); ap.add_argument('--runner-report',required=True,type=Path); ap.add_argument('--return-report',required=True,type=Path); ap.add_argument('--output',required=True,type=Path); a=ap.parse_args()
