        infos=z.infolist(); names=[i.filename for i in infos]; checks['crc']=z.testzip() is None; checks['single_root']={x.split('/',1)[0] for x in names}=={PACKAGE}; checks['no_duplicates']=len(names)==len(set(names)); checks['safe_paths']=all(not PurePosixPath(i.filename).is_absolute() and '..' not in PurePosixPath(i.filename).parts and '\\' not in i.filename for i in infos); checks['no_symlinks']=all(not stat.S_ISLNK((i.external_attr>>16)&0xffff) for i in infos)
        target={'/'.join(i.filename.split('/')[1:]):z.read(i) for i in infos if not i.is_dir()}; sr=s.namelist()[0].split('/',1)[0]; source={'/'.join(i.filename.split('/')[1:]):s.read(i) for i in s.infolist() if not i.is_dir()}; m=json.loads(target['package_manifest.json']); actual={p:sha(b) for p,b in target.items() if p!='package_manifest.json'}
        checks['manifest_exact_set']=set(m['files'])==set(actual); checks['manifest_receipts']=m['files']==actual; checks['manifest_identity']=m['install_name']==PACKAGE and m['source_package_sha256']==SOURCE_SHA and m['classification']=='DIAGNOSTIC_ONLY_NOT_FUNCTIONAL_FIX' and m['candidate_release'] is False and m['configuration_rebuilt'] is False and m['node0004_workload_rebuilt'] is False and m['numeric_analysis_repeated'] is False and m['functional_rtl_modified'] is False and m['server_action'] is False
