        frozen=[p for p in source if (p.startswith('workload/') or 'golden' in p.lower() or p.endswith('.bin')) and p in target]; checks['frozen_payload']=bool(frozen) and all(target[p].replace(PACKAGE.encode(),sr.encode())==source[p] for p in frozen)
