    reports={'build':load(a.build_report).get('deterministic_rebuild_equal') is True,'family':load(a.family_report).get('valid') is True,'shared':load(a.shared_report).get('pass') is True,'observer':load(a.observer_report).get('valid') is True,'runner':load(a.runner_report).get('valid') is True,'return':load(a.return_report).get('valid') is True}; checks.update({f'{k}_report':v for k,v in reports.items()})
    matrix={"package_bootstrap_path_runtime_d":{"applicability":"receipt_reuse","blocking":True,"pass":checks['family_report'] and checks['shared_report']},"runner_compile_finalizer":{"applicability":"receipt_reuse","blocking":True,"pass":checks['family_report'] and checks['runner_report']},"package_local_hdl_changed":{"applicability":"blocking_applicable","blocking":True,"pass":checks['observer_report']},"materialized_config":{"applicability":"not_applicable_byte_equal","blocking":False,"pass":True},"observer_canonical_changed":{"applicability":"blocking_applicable","blocking":True,"pass":checks['observer_report']},"return_result_gate":{"applicability":"receipt_reuse","blocking":True,"pass":checks['return_report']},"numeric_w3_golden":{"applicability":"record_only_byte_equal","blocking":False,"pass":checks['frozen_payload']},"unrelated_rtl":{"applicability":"not_applicable","blocking":False,"pass":True}}
